/**
 * JSZip 3.x Offline Standalone Distribution for Wardrobe Organizer PWA
 * Compliant with PKZIP 2.0 specifications.
 * Supports DEFLATE (via browser CompressionStream) and STORE compression.
 * Zero external dependencies. Works 100% offline.
 */

// --- CRC-32 Table Generation ---
const CRC32_TABLE = new Uint32Array(256);
for (let i = 0; i < 256; i++) {
  let c = i;
  for (let k = 0; k < 8; k++) {
    c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  }
  CRC32_TABLE[i] = c >>> 0;
}

function calculateCrc32(uint8Array) {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < uint8Array.length; i++) {
    crc = CRC32_TABLE[(crc ^ uint8Array[i]) & 0xFF] ^ (crc >>> 8);
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

// Convert Date to MS-DOS Date & Time format
function dateToDos(date = new Date()) {
  const d = (date instanceof Date && !isNaN(date.getTime())) ? date : new Date();
  const year = d.getFullYear();
  const dosYear = year >= 1980 ? year - 1980 : 0;
  const dosDate = (dosYear << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
  const dosTime = (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1);
  return { dosDate, dosTime };
}

// Convert MS-DOS Date & Time to JavaScript Date
function dosToDate(dosDate, dosTime) {
  const day = dosDate & 0x1F;
  const month = ((dosDate >> 5) & 0x0F) - 1;
  const year = ((dosDate >> 9) & 0x7F) + 1980;
  const second = (dosTime & 0x1F) * 2;
  const minute = (dosTime >> 5) & 0x3F;
  const hour = (dosTime >> 11) & 0x1F;
  return new Date(year, month, day, hour, minute, second);
}

// Helper: Normalize content to Uint8Array
async function toUint8Array(content) {
  if (content === null || content === undefined) {
    return new Uint8Array(0);
  }
  if (typeof content === 'string') {
    return new TextEncoder().encode(content);
  }
  if (content instanceof Uint8Array) {
    return content;
  }
  if (content instanceof ArrayBuffer) {
    return new Uint8Array(content);
  }
  if (typeof Blob !== 'undefined' && content instanceof Blob) {
    const ab = await content.arrayBuffer();
    return new Uint8Array(ab);
  }
  if (ArrayBuffer.isView(content)) {
    return new Uint8Array(content.buffer, content.byteOffset, content.byteLength);
  }
  return new TextEncoder().encode(String(content));
}

// Helper: Compress bytes using DEFLATE (CompressionStream) or fallback
async function deflateBytes(bytes) {
  if (typeof CompressionStream !== 'undefined') {
    try {
      const cs = new CompressionStream('deflate-raw');
      const writer = cs.writable.getWriter();
      writer.write(bytes);
      writer.close();
      const chunks = [];
      const reader = cs.readable.getReader();
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        chunks.push(value);
      }
      let totalLen = chunks.reduce((acc, c) => acc + c.length, 0);
      let out = new Uint8Array(totalLen);
      let offset = 0;
      for (const chunk of chunks) {
        out.set(chunk, offset);
        offset += chunk.length;
      }
      return out;
    } catch (e) {
      // Fallback if deflate-raw is not accepted by stream
      return null;
    }
  }
  return null;
}

// Helper: Decompress bytes using DEFLATE (DecompressionStream)
async function inflateBytes(bytes) {
  if (typeof DecompressionStream !== 'undefined') {
    const ds = new DecompressionStream('deflate-raw');
    const writer = ds.writable.getWriter();
    writer.write(bytes);
    writer.close();
    const chunks = [];
    const reader = ds.readable.getReader();
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      chunks.push(value);
    }
    let totalLen = chunks.reduce((acc, c) => acc + c.length, 0);
    let out = new Uint8Array(totalLen);
    let offset = 0;
    for (const chunk of chunks) {
      out.set(chunk, offset);
      offset += chunk.length;
    }
    return out;
  }
  throw new Error('[JSZip] DecompressionStream is required to inflate DEFLATE entries.');
}

/**
 * JSZipObject represents a file or directory entry in the ZIP archive.
 */
class JSZipObject {
  constructor(name, data, options = {}) {
    this.name = name;
    this._data = data; // Uint8Array | null
    this.dir = options.dir || name.endsWith('/');
    this.date = options.date || new Date();
    this.comment = options.comment || '';
    this._compressedData = options.compressedData || null;
    this._compressionMethod = options.compressionMethod || 0;
    this._crc32 = options.crc32 !== undefined ? options.crc32 : null;
    this._uncompressedSize = options.uncompressedSize !== undefined ? options.uncompressedSize : null;
    this._compression = options.compression || null;
    this._sourceBlob = options.sourceBlob || null;
    this._localHeaderOffset = options.localHeaderOffset !== undefined ? options.localHeaderOffset : null;
    this._compressedSize = options.compressedSize !== undefined ? options.compressedSize : 0;
  }

  /**
   * Release cached uncompressed/compressed buffers to keep memory usage low during streaming restores
   */
  releaseMemory() {
    this._data = null;
    if (this._sourceBlob) {
      this._compressedData = null;
    }
  }

  /**
   * Read compressed bytes lazily from _sourceBlob if needed
   */
  async _getCompressedBytes() {
    if (this._compressedData) {
      return this._compressedData;
    }
    if (this._sourceBlob && this._localHeaderOffset !== null) {
      const headerSlice = this._sourceBlob.slice(this._localHeaderOffset, this._localHeaderOffset + 30);
      const headerBuf = await headerSlice.arrayBuffer();
      const headerView = new DataView(headerBuf);
      if (headerView.getUint32(0, true) !== 0x04034b50) {
        throw new Error(`[JSZip] Corrupt local file header at offset ${this._localHeaderOffset}`);
      }
      const localNameLen = headerView.getUint16(26, true);
      const localExtraLen = headerView.getUint16(28, true);
      const dataStart = this._localHeaderOffset + 30 + localNameLen + localExtraLen;
      const dataSlice = this._sourceBlob.slice(dataStart, dataStart + this._compressedSize);
      const dataBuf = await dataSlice.arrayBuffer();
      return new Uint8Array(dataBuf);
    }
    return new Uint8Array(0);
  }

  /**
   * Return file content as specified type.
   * @param {'string'|'arraybuffer'|'uint8array'|'blob'} type
   * @returns {Promise<any>}
   */
  async async(type = 'string') {
    let uncompressed;
    if (this._data) {
      uncompressed = this._data;
    } else if (this._compressedData || this._sourceBlob) {
      const compBytes = await this._getCompressedBytes();
      if (this._compressionMethod === 8) {
        uncompressed = await inflateBytes(compBytes);
      } else {
        uncompressed = compBytes;
      }
      // Only cache small entries (<1MB) automatically so large video blobs don't accumulate in RAM
      if (uncompressed.byteLength < 1024 * 1024) {
        this._data = uncompressed;
      }
    } else if (this._rawInput !== undefined) {
      uncompressed = await toUint8Array(this._rawInput);
    } else {
      uncompressed = new Uint8Array(0);
    }

    switch (type.toLowerCase()) {
      case 'string':
      case 'text':
        return new TextDecoder('utf-8').decode(uncompressed);
      case 'arraybuffer':
        if (uncompressed.byteOffset === 0 && uncompressed.byteLength === uncompressed.buffer.byteLength) {
          return uncompressed.buffer;
        }
        return uncompressed.buffer.slice(uncompressed.byteOffset, uncompressed.byteOffset + uncompressed.byteLength);
      case 'uint8array':
        return uncompressed;
      case 'blob':
        return new Blob([uncompressed], { type: 'application/octet-stream' });
      default:
        throw new Error(`[JSZip] Unsupported output type: ${type}`);
    }
  }
}

/**
 * JSZip class.
 */
export class JSZip {
  constructor() {
    /** @type {Record<string, JSZipObject>} */
    this.files = {};
    this.root = '';
  }

  /**
   * Create or update a file in the zip.
   * @param {string} name - File path.
   * @param {any} [data] - Content.
   * @param {object} [options] - Options.
   */
  file(name, data, options = {}) {
    // 1-argument overload: getter
    if (arguments.length === 1) {
      const fullPath = this.root + name;
      const cleanPath = fullPath.replace(/\\/g, '/');
      return this.files[cleanPath] || null;
    }

    // 2+ arguments: setter
    const fullPath = (this.root + name).replace(/\\/g, '/');
    const entry = new JSZipObject(fullPath, null, {
      dir: false,
      date: options.date || new Date(),
      comment: options.comment || '',
      crc32: options.crc32,
      uncompressedSize: options.uncompressedSize,
      compression: options.compression || null
    });
    entry._rawInput = data;
    this.files[fullPath] = entry;
    return this;
  }

  /**
   * Create or navigate to a folder.
   * @param {string} name - Folder name.
   */
  folder(name) {
    if (!name) return this;
    let cleanName = (this.root + name).replace(/\\/g, '/');
    if (!cleanName.endsWith('/')) cleanName += '/';

    if (!this.files[cleanName]) {
      this.files[cleanName] = new JSZipObject(cleanName, new Uint8Array(0), {
        dir: true,
        date: new Date()
      });
    }

    const child = new JSZip();
    child.files = this.files;
    child.root = cleanName;
    return child;
  }

  /**
   * Iterate over all entries.
   * @param {(relativePath: string, file: JSZipObject) => void} callback
   */
  forEach(callback) {
    for (const [name, file] of Object.entries(this.files)) {
      if (name.startsWith(this.root)) {
        const rel = name.slice(this.root.length);
        if (rel) callback(rel, file);
      }
    }
  }

  /**
   * Filter entries.
   * @param {(relativePath: string, file: JSZipObject) => boolean} predicate
   */
  filter(predicate) {
    const results = [];
    this.forEach((rel, file) => {
      if (predicate(rel, file)) results.push(file);
    });
    return results;
  }

  /**
   * Generate complete ZIP archive.
   * Uses zero-copy Blob parts when outputType === 'blob' so large video archives never exceed mobile RAM limits.
   * @param {object} [options]
   * @param {(progress: { percent: number, currentFile: string }) => void} [onUpdate]
   */
  async generateAsync(options = {}, onUpdate) {
    const outputType = (options.type || 'blob').toLowerCase();
    const mimeType = options.mimeType || 'application/zip';
    const defaultCompression = (options.compression || '').toUpperCase();

    const entries = Object.entries(this.files);
    const totalFiles = entries.length;
    let processed = 0;

    const fileRecords = [];

    // Process all files & folders
    for (const [name, entry] of entries) {
      if (onUpdate) {
        onUpdate({
          percent: Math.round((processed / (totalFiles || 1)) * 100),
          currentFile: name
        });
      }

      const entryCompression = (entry._compression || defaultCompression || 'STORE').toUpperCase();
      const requestDeflate = entryCompression === 'DEFLATE';

      // Fast path for pre-measured Blob inputs with STORE compression when building a Blob archive
      if (
        outputType === 'blob' &&
        !requestDeflate &&
        typeof Blob !== 'undefined' &&
        entry._rawInput instanceof Blob &&
        typeof entry._crc32 === 'number' &&
        typeof entry._uncompressedSize === 'number'
      ) {
        const blobInput = entry._rawInput;
        delete entry._rawInput;
        const nameBytes = new TextEncoder().encode(name);
        const { dosDate, dosTime } = dateToDos(entry.date);

        fileRecords.push({
          name,
          nameBytes,
          compressedPart: blobInput,
          uncompressedSize: entry._uncompressedSize,
          compressedSize: blobInput.size,
          crc: entry._crc32 >>> 0,
          compressionMethod: 0,
          dosDate,
          dosTime,
          isDir: entry.dir
        });
        processed++;
        continue;
      }

      let rawBytes;
      if (entry._rawInput !== undefined) {
        rawBytes = await toUint8Array(entry._rawInput);
        delete entry._rawInput;
      } else if (entry._data) {
        rawBytes = entry._data;
      } else {
        rawBytes = new Uint8Array(0);
      }

      const uncompressedSize = rawBytes.length;
      const crc = typeof entry._crc32 === 'number' ? (entry._crc32 >>> 0) : calculateCrc32(rawBytes);

      let compressedBytes = rawBytes;
      let compressionMethod = 0; // STORE

      if (requestDeflate && uncompressedSize > 0) {
        const deflated = await deflateBytes(rawBytes);
        if (deflated && deflated.length < uncompressedSize) {
          compressedBytes = deflated;
          compressionMethod = 8; // DEFLATE
        }
      }

      const nameBytes = new TextEncoder().encode(name);
      const { dosDate, dosTime } = dateToDos(entry.date);

      fileRecords.push({
        name,
        nameBytes,
        compressedPart: compressedBytes,
        uncompressedSize,
        compressedSize: compressedBytes.length,
        crc,
        compressionMethod,
        dosDate,
        dosTime,
        isDir: entry.dir
      });

      processed++;
    }

    // Build ZIP Binary Layout
    const localParts = [];
    let currentOffset = 0;

    for (const rec of fileRecords) {
      rec.offset = currentOffset;

      // Local File Header (30 bytes + name length)
      const lfh = new Uint8Array(30 + rec.nameBytes.length);
      const view = new DataView(lfh.buffer);

      view.setUint32(0, 0x04034b50, true); // Local file header signature
      view.setUint16(4, 20, true);          // Version needed to extract (2.0)
      view.setUint16(6, 0x0800, true);       // General purpose bit flag (UTF-8)
      view.setUint16(8, rec.compressionMethod, true); // Compression method
      view.setUint16(10, rec.dosTime, true);
      view.setUint16(12, rec.dosDate, true);
      view.setUint32(14, rec.crc, true);
      view.setUint32(18, rec.compressedSize, true);
      view.setUint32(22, rec.uncompressedSize, true);
      view.setUint16(26, rec.nameBytes.length, true);
      view.setUint16(28, 0, true);          // Extra field length
      lfh.set(rec.nameBytes, 30);

      localParts.push(lfh);
      localParts.push(rec.compressedPart);
      rec.compressedPart = null;

      currentOffset += lfh.length + rec.compressedSize;
    }

    const centralDirOffset = currentOffset;
    const cdHeaders = [];

    // Central Directory File Headers (46 bytes + name length)
    for (const rec of fileRecords) {
      const cdh = new Uint8Array(46 + rec.nameBytes.length);
      const view = new DataView(cdh.buffer);

      view.setUint32(0, 0x02014b50, true);  // Central directory file header signature
      view.setUint16(4, 20, true);          // Version made by
      view.setUint16(6, 20, true);          // Version needed to extract
      view.setUint16(8, 0x0800, true);       // UTF-8 flag
      view.setUint16(10, rec.compressionMethod, true);
      view.setUint16(12, rec.dosTime, true);
      view.setUint16(14, rec.dosDate, true);
      view.setUint32(16, rec.crc, true);
      view.setUint32(20, rec.compressedSize, true);
      view.setUint32(24, rec.uncompressedSize, true);
      view.setUint16(28, rec.nameBytes.length, true);
      view.setUint16(30, 0, true);          // Extra field length
      view.setUint16(32, 0, true);          // File comment length
      view.setUint16(34, 0, true);          // Disk number start
      view.setUint16(36, 0, true);          // Internal file attributes
      view.setUint32(38, rec.isDir ? 0x10 : 0, true); // External file attributes
      view.setUint32(42, rec.offset, true); // Relative offset of local header
      cdh.set(rec.nameBytes, 46);

      cdHeaders.push(cdh);
      currentOffset += cdh.length;
    }

    const centralDirSize = currentOffset - centralDirOffset;

    // End of Central Directory Record (22 bytes)
    const eocd = new Uint8Array(22);
    const eocdView = new DataView(eocd.buffer);
    eocdView.setUint32(0, 0x06054b50, true); // EOCD signature
    eocdView.setUint16(4, 0, true);          // Number of this disk
    eocdView.setUint16(6, 0, true);          // Disk with start of CD
    eocdView.setUint16(8, fileRecords.length, true);  // Total entries on disk
    eocdView.setUint16(10, fileRecords.length, true); // Total entries
    eocdView.setUint32(12, centralDirSize, true);     // Size of central directory
    eocdView.setUint32(16, centralDirOffset, true);   // Offset of start of CD
    eocdView.setUint16(20, 0, true);         // ZIP comment length

    if (onUpdate) {
      onUpdate({ percent: 100, currentFile: '' });
    }

    // Flat Blob assembly: avoids both nested sub-Blobs (which fail in mobile download managers) and huge contiguous allocations
    if (outputType === 'blob') {
      const allParts = [...localParts, ...cdHeaders, eocd];
      localParts.length = 0;
      cdHeaders.length = 0;
      fileRecords.length = 0;
      return new Blob(allParts, { type: mimeType });
    }

    const allParts = [...localParts, ...cdHeaders, eocd];
    let totalArchiveSize = allParts.reduce((acc, p) => acc + p.length, 0);

    const finalArchive = new Uint8Array(totalArchiveSize);
    let writePos = 0;
    for (const part of allParts) {
      finalArchive.set(part, writePos);
      writePos += part.length;
    }

    switch (outputType) {
      case 'arraybuffer':
        return finalArchive.buffer;
      case 'uint8array':
        return finalArchive;
      default:
        return new Blob([finalArchive], { type: mimeType });
    }
  }

  /**
   * Load and parse an existing ZIP archive.
   * Supports lazy Blob-slicing when given a Blob/File so large archives don't load into RAM all at once.
   * @param {Blob|File|ArrayBuffer|Uint8Array} data
   * @returns {Promise<JSZip>}
   */
  static async loadAsync(data) {
    if (typeof Blob !== 'undefined' && data instanceof Blob) {
      return JSZip._loadFromBlobAsync(data);
    }

    const bytes = await toUint8Array(data);
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);

    // Find End of Central Directory (EOCD) by scanning backwards
    let eocdOffset = -1;
    for (let i = bytes.length - 22; i >= 0; i--) {
      if (view.getUint32(i, true) === 0x06054b50) {
        eocdOffset = i;
        break;
      }
    }

    if (eocdOffset === -1) {
      throw new Error('[JSZip] Invalid ZIP archive: EOCD signature not found.');
    }

    const totalEntries = view.getUint16(eocdOffset + 10, true);
    const cdOffset = view.getUint32(eocdOffset + 16, true);

    const zip = new JSZip();
    let cdPos = cdOffset;

    for (let entryIdx = 0; entryIdx < totalEntries; entryIdx++) {
      if (view.getUint32(cdPos, true) !== 0x02014b50) {
        throw new Error(`[JSZip] Corrupt central directory header at offset ${cdPos}`);
      }

      const method = view.getUint16(cdPos + 10, true);
      const dosTime = view.getUint16(cdPos + 12, true);
      const dosDate = view.getUint16(cdPos + 14, true);
      const crc32 = view.getUint32(cdPos + 16, true);
      const compressedSize = view.getUint32(cdPos + 20, true);
      const uncompressedSize = view.getUint32(cdPos + 24, true);
      const nameLen = view.getUint16(cdPos + 28, true);
      const extraLen = view.getUint16(cdPos + 30, true);
      const commentLen = view.getUint16(cdPos + 32, true);
      const localHeaderOffset = view.getUint32(cdPos + 42, true);

      const nameBytes = bytes.subarray(cdPos + 46, cdPos + 46 + nameLen);
      const filename = new TextDecoder('utf-8').decode(nameBytes);

      // Read Local File Header to locate file content
      if (view.getUint32(localHeaderOffset, true) !== 0x04034b50) {
        throw new Error(`[JSZip] Corrupt local file header at offset ${localHeaderOffset}`);
      }
      const localNameLen = view.getUint16(localHeaderOffset + 26, true);
      const localExtraLen = view.getUint16(localHeaderOffset + 28, true);
      const dataStart = localHeaderOffset + 30 + localNameLen + localExtraLen;
      const fileDataBytes = bytes.subarray(dataStart, dataStart + compressedSize);

      const isDir = filename.endsWith('/');
      const date = dosToDate(dosDate, dosTime);

      const zipObject = new JSZipObject(filename, method === 0 ? fileDataBytes : null, {
        dir: isDir,
        date,
        compressedData: fileDataBytes,
        compressionMethod: method,
        crc32,
        uncompressedSize
      });

      zip.files[filename] = zipObject;

      cdPos += 46 + nameLen + extraLen + commentLen;
    }

    return zip;
  }

  /**
   * Memory-safe Blob/File ZIP reader: reads only Central Directory and slices individual entries on demand
   */
  static async _loadFromBlobAsync(blob) {
    const fileSize = blob.size;
    if (fileSize < 22) {
      throw new Error('[JSZip] Invalid ZIP archive: file too small.');
    }

    const maxEocdSearch = Math.min(fileSize, 65558);
    const tailStart = fileSize - maxEocdSearch;
    const tailBuf = await blob.slice(tailStart, fileSize).arrayBuffer();
    const tailView = new DataView(tailBuf);

    let eocdRelOffset = -1;
    for (let i = tailBuf.byteLength - 22; i >= 0; i--) {
      if (tailView.getUint32(i, true) === 0x06054b50) {
        eocdRelOffset = i;
        break;
      }
    }

    if (eocdRelOffset === -1) {
      throw new Error('[JSZip] Invalid ZIP archive: EOCD signature not found.');
    }

    const totalEntries = tailView.getUint16(eocdRelOffset + 10, true);
    const cdSize = tailView.getUint32(eocdRelOffset + 12, true);
    const cdOffset = tailView.getUint32(eocdRelOffset + 16, true);

    const cdBuf = await blob.slice(cdOffset, cdOffset + cdSize).arrayBuffer();
    const cdBytes = new Uint8Array(cdBuf);
    const cdView = new DataView(cdBuf);

    const zip = new JSZip();
    let cdPos = 0;

    for (let entryIdx = 0; entryIdx < totalEntries; entryIdx++) {
      if (cdPos + 46 > cdBuf.byteLength || cdView.getUint32(cdPos, true) !== 0x02014b50) {
        throw new Error(`[JSZip] Corrupt central directory header at offset ${cdOffset + cdPos}`);
      }

      const method = cdView.getUint16(cdPos + 10, true);
      const dosTime = cdView.getUint16(cdPos + 12, true);
      const dosDate = cdView.getUint16(cdPos + 14, true);
      const crc32 = cdView.getUint32(cdPos + 16, true);
      const compressedSize = cdView.getUint32(cdPos + 20, true);
      const uncompressedSize = cdView.getUint32(cdPos + 24, true);
      const nameLen = cdView.getUint16(cdPos + 28, true);
      const extraLen = cdView.getUint16(cdPos + 30, true);
      const commentLen = cdView.getUint16(cdPos + 32, true);
      const localHeaderOffset = cdView.getUint32(cdPos + 42, true);

      const nameBytes = cdBytes.subarray(cdPos + 46, cdPos + 46 + nameLen);
      const filename = new TextDecoder('utf-8').decode(nameBytes);

      const isDir = filename.endsWith('/');
      const date = dosToDate(dosDate, dosTime);

      const zipObject = new JSZipObject(filename, null, {
        dir: isDir,
        date,
        compressionMethod: method,
        crc32,
        uncompressedSize,
        sourceBlob: blob,
        localHeaderOffset,
        compressedSize
      });

      zip.files[filename] = zipObject;
      cdPos += 46 + nameLen + extraLen + commentLen;
    }

    return zip;
  }
}

export { calculateCrc32 };

// Global window attachment for script tag compatibility
if (typeof window !== 'undefined') {
  window.JSZip = JSZip;
}

export default JSZip;
